<script lang="ts">
	import { onMount } from "svelte";
	import Toc from "svelte-toc";
	import { Breadcrumb, BreadcrumbItem } from "flowbite-svelte";
	import * as d3 from "d3";

	import SinagBar from "$lib/SinagBar.svelte";
	import SalPlate from "$lib/SalPlate.svelte";
	import BukPlate from "$lib/BukPlate.svelte";
	import IndPlate from "$lib/IndPlate.svelte";

	import HeaderSquare from "$lib/img/header-square.png";
	import HeaderWide from "$lib/img/header-wide.png";
	import TurnoutPie from "$lib/img/turnout-pie.png";
	import TurnoutTrend from "$lib/img/turnout-trend.png";

	import "./global.scss";
	import PageButton from "$lib/PageButton.svelte";

	const svgIds = ["_2021-range", "_2022-range", "_2023-range", "_2024-range"];

	onMount(() => {
		for (const id of svgIds) {
			const svg = d3.select(".svg-contain").select(`#${id}`);
			console.log(id);
			const tooltipCtx = d3.select(".svg-contain");
			svg.on("mouseover", () => {
				tooltipCtx.select(`.${id}`).style("opacity", "1");
			})
				.on("touchend", () => {
					tooltipCtx.select(`.${id}`).style("opacity", "1");
					setTimeout(() => {
						tooltipCtx.select(`.${id}`).style("opacity", "0");
					}, 3500);
				})
				.on("mousemove", (s) => {
					tooltipCtx
						.select(`.${id}`)
						.style(
							"left",
							`${Math.max(0, d3.pointer(s, tooltipCtx.node())[0])}px`
						)
						.style(
							"top",
							d3.pointer(s, tooltipCtx.node())[1] + "px"
						);
				})
				.on("mouseout touchmove touchcancel touchstart", () => {
					tooltipCtx.select(`.${id}`).style("opacity", "0");
				});
		}
	});
</script>

